// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
DateTime earliest = DateTime.MinValue;
for (int year = 1; year <= 9999; year++)
{
    var d = new DateTime(year, 1, 13);
    for (int m = 0; m < 12; m++)
    {
        var candidate = d.AddMonths(m);
        if (candidate.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == DateTime.MinValue)
            {
                earliest = candidate;
            }
        }
    }
    if (earliest != DateTime.MinValue) break;
}
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in a full 400-year Gregorian cycle (years 1–400)
int count = 0;
var monthlyCounts = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            monthlyCounts[month - 1]++;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();
Console.WriteLine("Distribution by month:");
for (int m = 0; m < 12; m++)
{
    var name = new DateTime(1, m + 1, 1).ToString("MMMM");
    Console.WriteLine($"  {name,-12} {monthlyCounts[m],3}");
}

// Bonus: which day-of-week lands on the 13th most often?
Console.WriteLine();
Console.WriteLine("13th-of-month frequency by day of week (400-year cycle):");
var dowCounts = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        dowCounts[(int)new DateTime(year, month, 13).DayOfWeek]++;
    }
}
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
{
    Console.WriteLine($"  {dow,-12} {dowCounts[(int)dow],3}");
}

